/// Add pre-conditions and post-conditions to the inductiveness lemma.
///
/// For 'init' routines:
///   requires(initialized(post, ...));
///   ensures(post.invariant());
///
/// For normal transitions:
///   requires(pre.invariant() && transition(pre, post, ...));
///   ensures(post.invariant());
///
/// For 'readonly' transitions, there is no need to prove inductiveness.
/// We should have already ruled out the existence of such lemmas.
fn lemma_update_body(bundle: &SMBundle, l: &Lemma, func: &mut ImplItemFn) {
    let trans = get_transition(&bundle.sm.transitions, &l.purpose.transition.to_string())
        .expect("transition");

    let precondition = if trans.kind == TransitionKind::Init {
        let trans_name =
            Ident::new(&(l.purpose.transition.to_string()), l.purpose.transition.span());
        let trans_args: Vec<&Pat> = l.func.sig.inputs.iter().map(|i| left_of_colon(i)).collect();
        quote! { Self::#trans_name(#(#trans_args),*) }
    } else {
        let trans_name_strong = Ident::new(
            &(l.purpose.transition.to_string() + "_strong"),
            l.purpose.transition.span(),
        );
        let self_ty = get_self_ty_turbofish(&bundle.sm);
        let trans_args: Vec<&Pat> = l.func.sig.inputs.iter().map(|i| left_of_colon(i)).collect();
        quote! { pre.invariant() && #self_ty::#trans_name_strong(#(#trans_args),*) }
    };

    let mut stmts = vec![
        Stmt::Expr(
            Expr::Verbatim(quote_vstd! { vstd =>
                #vstd::prelude::requires(
                    #precondition
                )
            }),
            Some(token::Semi { spans: [l.func.span()] }),
        ),
        Stmt::Expr(
            Expr::Verbatim(quote_vstd! { vstd =>
                #vstd::prelude::ensures(
                    post.invariant()
                )
            }),
            Some(token::Semi { spans: [l.func.span()] }),
        ),
        Stmt::Expr(
            Expr::Block(ExprBlock { attrs: vec![], label: None, block: func.block.clone() }),
            None,
        ),
    ];
    for inv in &bundle.extras.invariants {
        let inv_ident = &inv.func.sig.ident;
        let inv_name = inv_ident.to_string();
        let lemma_msg_ident = Ident::new(&format!("lemma_msg_{:}", inv_name), inv_ident.span());
        let span = l.func.span();
        stmts.push(Stmt::Expr(
            Expr::Verbatim(quote_spanned! { span =>
                Self::#lemma_msg_ident(post)
            }),
            Some(token::Semi { spans: [l.func.span()] }),
        ));

/// ## Example
///
/// ```rust
/// let m: IMap<int, int> = imap![1 => 10, 2 => 11];
/// assert(m.values() == iset![10int, 11int]) by {
///     assert(m.contains_key(1));
///     assert(m.contains_key(2));
///     assert(m.values() =~= iset![10int, 11int]);
/// }
/// ```
pub open spec fn values(self) -> ISet<V> {
    ISet::<V>::new(|v: V| self.contains_value(v))
}

///
/// Returns the set of key-value pairs representing the map
///
/// ## Example
///
/// ```rust
/// let m: IMap<int, int> = imap![1 => 10, 2 => 11];
/// assert(m.kv_pairs() == iset![(1int, 10int), (2int, 11int)] by {
///     assert(m.contains_pair(1int, 10int));
///     assert(m.contains_pair(2int, 11int));
///     assert(m.kv_pairs() =~= iset![(1int, 10int), (2int, 11int)]);
/// }
/// ```
pub open spec fn kv_pairs(self) -> ISet<(K, V)> {
    ISet::<(K, V)>::new(|kv: (K, V)| self.dom().contains(kv.0) && self[kv.0] == kv.1)
}

/// Returns true if the key `k` is in the domain of `self`, and it maps to the value `v`.
pub open spec fn contains_pair(self, k: K, v: V) -> bool {
    // We use the implication below to make sure that the solver tries to prove
    // `self.dom().contains(k)` first. That fact is sometimes necessary to trigger
    // a quantifier helpful in proving `self[k] == v`.
    &&& self.dom().contains(k)
    &&& self.dom().contains(k) ==> self[k] == v
}

/// Returns true if `m1` is _contained in_ `m2`, i.e., the domain of `m1` is a subset
/// of the domain of `m2`, and they agree on all values in `m1`.
///
/// ## Example
///
/// ```rust
/// assert(
///    imap![1 => 10, 2 => 11].le(imap![1 => 10, 2 => 11, 3 => 12])
/// );
/// ```
pub open spec fn submap_of(self, m2: Self) -> bool {
    forall|k: K| #[trigger]
        self.dom().contains(k) ==> #[trigger] m2.dom().contains(k) && self[k] == m2[k]
}

#[verifier::inline]
pub open spec fn spec_le(self, m2: Self) -> bool {
    self.submap_of(m2)
}

/// Gives the union of two maps, defined as:
///  * The domain is the union of the two input maps.
///  * For a given key in _both_ input maps, it maps to the same value that it maps to in the _right_ map (`m2`).
///  * For any other key in either input map (but not both), it maps to the same value
///    as it does in that map.
///
/// ## Example
///
/// ```rust
/// assert(
///    map![1 => 10, 2 => 11].union_prefer_right(map![1 => 20, 3 => 13])
///    =~= map![1 => 20, 2 => 11, 3 => 13]);
/// ```
pub open spec fn union_prefer_right(self, m2: Self) -> Self {
    Self::new(
        |k: K| self.dom().contains(k) || m2.dom().contains(k),
        |k: K|
            if m2.dom().contains(k) {
