        let sops = crate::simplify_asserts::simplify_asserts(sops);
        let sops = annotate_extractions(&sops);
        simpl_conjunct_vec(&sops, None)
    } else {
        // Leave the assertions is; they will be included as normal conjuncts
        let sops = annotate_extractions(&sops);
        simpl_conjunct_vec(&sops, None)
    };

    match x {
        Some(e) => e,
        None => quote! { true },
    }
}

