            };

            // request_stored_inv: requests unchanged.
            // For i == j: pre.slots[j] = false (from have), but request_stored_inv requires
            // slots[i] = true. So request_stored_pre(j) = false, hence post doesn't have it.
            // For i != j: all unchanged.
            assert forall |i: nat| #[trigger] post.request_stored(i)
                implies post.client_waiting(i)
                    && post.requests.index(i).rid == post.clients.index(i).get_Waiting_rid()
                    && post.slots.index(i) by {
                if i == j {
                    // pre.slots[j] = false, so request_stored_pre(j) = false
                    // (by request_stored_inv, request_stored => slots = true)
                    assert(pre.request_stored(j));  // leads to contradiction
                    assert(pre.slots.index(j));  // but pre.slots[j] = false
                } else {
                    assert(pre.request_stored(i));
                    assert(pre.client_waiting(i));
                    // clients[i] unchanged for i != j
                    assert(post.client_waiting(i));
                    assert(post.slots.index(i));
                }
            };

            // response_stored_inv: for i == j, we withdrew the response, so not in post.
            // For i != j: responses[i] unchanged. clients[i] unchanged. slots[i] unchanged.
            assert forall |i: nat| #[trigger] post.response_stored(i)
                implies post.client_waiting(i)
                    && post.responses.index(i).rid == post.clients.index(i).get_Waiting_rid()
                    && !post.slots.index(i) by {
                if i == j {
                    // response[j] was withdrawn, so post.response_stored(j) = false
                    // This branch is unreachable
                } else {
                    assert(pre.response_stored(i));
                    assert(pre.client_waiting(i));
                    // clients[i] unchanged for i != j
                    assert(post.client_waiting(i));
                    assert(post.responses.index(i).rid == post.clients.index(i).get_Waiting_rid());
                    assert(!post.slots.index(i));
                }
            };

            // combiner_has_inv: combiner unchanged, clients[j] changed to Idle,
            // but combiner_has_pre(j) would require client_waiting_pre(j) = true, which holds.
            // However we need to check if combiner_has_post(j) could still hold.
            // combiner_has uses valid_idx and combiner state; combiner unchanged.
            // combiner_has_post(j) = combiner_has_pre(j). But pre.combiner_has_inv:
            // combiner_has_pre(j) => slots_pre[j] = true. But slots[j] = false. Contradiction.
            // So combiner_has_post(j) = false. For i != j: clients[i] unchanged.
            assert forall |i: nat| #[trigger] post.combiner_has(i)
                implies post.client_waiting(i)
                    && post.slots.index(i)
                    && post.combiner_rid(i) == post.clients.index(i).get_Waiting_rid()
                    && !post.request_stored(i) by {
                // combiner unchanged, so post.combiner_has(i) = pre.combiner_has(i)
                assert(pre.combiner_has(i));
                // pre.combiner_has_inv => slots_pre[i] = true
                assert(pre.slots.index(i));
                // For i == j: slots[j] = false, but we just said slots_pre[i] = true.
                // So i != j. For i != j: clients[i] unchanged.
                assert(pre.client_waiting(i));
                assert(pre.combiner_rid(i) == pre.clients.index(i).get_Waiting_rid());
                assert(!pre.request_stored(i));
            };
        }

        ///// Combiner transitions

        transition!{
            combiner_recv() {
                require(pre.combiner.is_Collecting());
                let j = pre.combiner.get_Collecting_elems().len();
                require(0 <= j && j < pre.num_clients);

                // Observe that the slot has been set to 'true'
                have slots >= [j => true];

                // Withdraw a request
                withdraw requests -= [j => let request] by {
                    assert(pre.valid_idx(j));
                    assert(pre.client_waiting(j));
                    assert(pre.request_stored(j));
                };

                // Update combiner's local state to remember we withdrew a request with this ID
                update combiner = Combiner::Collecting{
                    elems: pre.combiner.get_Collecting_elems().push(Option::Some(request.rid)),
                };
            }
        }

        #[inductive(combiner_recv)]
        fn combiner_recv_inductive(pre: Self, post: Self) {
            let j = pre.combiner.get_Collecting_elems().len();
            let elems = pre.combiner.get_Collecting_elems();
            let new_elems = elems.push(Option::Some(pre.requests.index(j).rid));

            // not_waiting_inv: clients and slots unchanged. Automatic.

            // waiting_inv: for i == j, combiner_has_post(j) is now true.
            // For i != j with combiner_has_pre(i): i < j, and combiner_has_post(i) holds too.
            assert forall |i: nat| #[trigger] post.client_waiting(i)
                implies post.request_stored(i) || post.response_stored(i) || post.combiner_has(i) by {
                if i == j {
                    // post.combiner = Collecting{new_elems}, new_elems.len() = j+1 > j,
                    // and new_elems[j] = Some(request.rid).is_Some() = true
                    assert(post.combiner_has(j));
                } else {
                    assert(pre.client_waiting(i));
                    if pre.request_stored(i) {
                        // requests[j] was withdrawn; i != j so requests[i] unchanged
                        assert(post.request_stored(i));
                    } else if pre.response_stored(i) {
                        assert(post.response_stored(i));
                    } else {
                        assert(pre.combiner_has(i));
                        // pre.combiner_has(i): i < j && elems[i].is_Some()
                        // post.combiner_has(i): i < j+1 && new_elems[i].is_Some()
                        // Since i < j < j+1 and new_elems[i] = elems[i] (for i < j = elems.len())
                        assert(post.combiner_has(i));
                    }
                }
            };

            // request_stored_inv: requests[j] was withdrawn. For i == j: not in post.
            // For i != j: requests[i] unchanged. clients and slots unchanged.
            assert forall |i: nat| #[trigger] post.request_stored(i)
                implies post.client_waiting(i)
                    && post.requests.index(i).rid == post.clients.index(i).get_Waiting_rid()
                    && post.slots.index(i) by {
                if i == j {
                    // request[j] was withdrawn, so not in post. Unreachable.
                    // Actually need to verify this: pre.request_stored(j) is true (from transition),
                    // but post.request_stored(j) = false after withdrawal.
                } else {
                    assert(pre.request_stored(i));
                    assert(pre.client_waiting(i));
                    assert(pre.slots.index(i));
                }
            };

            // response_stored_inv: responses unchanged. For all i: same as pre.
            // clients and slots unchanged.
            assert forall |i: nat| #[trigger] post.response_stored(i)
                implies post.client_waiting(i)
                    && post.responses.index(i).rid == post.clients.index(i).get_Waiting_rid()
                    && !post.slots.index(i) by {
                assert(pre.response_stored(i));
                assert(pre.client_waiting(i));
                assert(!pre.slots.index(i));
            };

            // combiner_has_inv: for i == j, new: client_waiting(j), slots[j] = true,
            // combiner_rid_post(j) = new_elems[j].get_Some_0() = request.rid,
            // request.rid = clients[j].get_Waiting_rid() (from request_stored_inv_pre).
            // !request_stored_post(j) since we withdrew it.
            // For i < j (combiner_has_post(i) = combiner_has_pre(i)): pre invariant applies.
            assert forall |i: nat| #[trigger] post.combiner_has(i)
                implies post.client_waiting(i)
                    && post.slots.index(i)
                    && post.combiner_rid(i) == post.clients.index(i).get_Waiting_rid()
                    && !post.request_stored(i) by {
                if i == j {
                    // combiner_has_post(j): j < new_elems.len() = j+1 and new_elems[j] = Some(...)
                    assert(post.client_waiting(j));
                    assert(post.slots.index(j));
                    // combiner_rid_post(j) = new_elems[j].get_Some_0() = request.rid
                    // from request_stored_inv_pre: request.rid = clients[j].get_Waiting_rid()
                    assert(pre.request_stored(j));
                    assert(pre.requests.index(j).rid == pre.clients.index(j).get_Waiting_rid());
                    assert(post.combiner_rid(j) == post.clients.index(j).get_Waiting_rid());
                    // request was withdrawn, so not in post
                    assert(!post.request_stored(j));
                } else {
                    // combiner_has_post(i): i < j+1 && new_elems[i].is_Some()
                    // Since i != j and i < j+1: i < j. So new_elems[i] = elems[i].
                    // Thus combiner_has_pre(i) holds.
                    assert(pre.combiner_has(i));
                    assert(pre.client_waiting(i));
                    assert(pre.slots.index(i));
                    assert(pre.combiner_rid(i) == pre.clients.index(i).get_Waiting_rid());
                    assert(!pre.request_stored(i));
                    // post.combiner_rid(i) = new_elems[i].get_Some_0() = elems[i].get_Some_0() = pre.combiner_rid(i)
                    assert(post.combiner_rid(i) == post.clients.index(i).get_Waiting_rid());
                    // requests[i] unchanged for i != j
                    assert(!post.request_stored(i));
                }
            };
        }

        transition!{
            combiner_skip() {
                require(pre.combiner.is_Collecting());
                let j = pre.combiner.get_Collecting_elems().len();
                require(0 <= j && j < pre.num_clients);

                // In practice, this happens when slot j is set to false, so we could add this:
                //    have slots >= [j => false];
                // but it's not necessary

                // Update combiner's local state to remember that we didn't withdraw
                // anything here.
                update combiner = Combiner::Collecting{
                    elems: pre.combiner.get_Collecting_elems().push(Option::None),
                };
            }
        }

        #[inductive(combiner_skip)]
        fn combiner_skip_inductive(pre: Self, post: Self) {
            let j = pre.combiner.get_Collecting_elems().len();
            let elems = pre.combiner.get_Collecting_elems();
            let new_elems = elems.push(Option::None);

            // clients_size: new_elems.len() = j+1 <= num_clients (j < num_clients)
            // Automatic.

            // not_waiting_inv: clients and slots unchanged. Automatic.

            // waiting_inv: combiner changed. For i == j: combiner_has_post(j) = false
            // (new_elems[j] = None). So client_waiting(j) ==> request_stored or response_stored.
            // Both unchanged.
            assert forall |i: nat| #[trigger] post.client_waiting(i)
                implies post.request_stored(i) || post.response_stored(i) || post.combiner_has(i) by {
                // clients unchanged so post.client_waiting(i) = pre.client_waiting(i)
                assert(pre.client_waiting(i));
                if pre.request_stored(i) {
                    assert(post.request_stored(i));
                } else if pre.response_stored(i) {
                    assert(post.response_stored(i));
                } else {
                    assert(pre.combiner_has(i));
                    // pre.combiner_has(i): i < j && elems[i].is_Some()
                    // Since i < j < j+1 and new_elems[i] = elems[i] for i < j:
                    assert(post.combiner_has(i));
                }
            };

            // request_stored_inv: requests, clients, slots all unchanged. Automatic.
            // response_stored_inv: responses, clients, slots all unchanged. Automatic.

            // combiner_has_inv: post.combiner_has(i) requires i < j+1 && new_elems[i].is_Some().
            // new_elems[j] = None, so i != j. For i < j: new_elems[i] = elems[i], so
            // post.combiner_has(i) = pre.combiner_has(i). Pre invariant applies.
            assert forall |i: nat| #[trigger] post.combiner_has(i)
                implies post.client_waiting(i)
                    && post.slots.index(i)
                    && post.combiner_rid(i) == post.clients.index(i).get_Waiting_rid()
                    && !post.request_stored(i) by {
                // post.combiner_has(i): i < j+1 && new_elems[i].is_Some()
                // new_elems[i] = elems[i] for i < j (since elems.len() = j)
                // new_elems[j] = None, so post.combiner_has(j) = false
                // Thus i < j, so pre.combiner_has(i) holds
                assert(pre.combiner_has(i));
                assert(pre.client_waiting(i));
                assert(pre.slots.index(i));
                assert(pre.combiner_rid(i) == pre.clients.index(i).get_Waiting_rid());
                assert(!pre.request_stored(i));
                // post.combiner_rid(i) = new_elems[i].get_Some_0() = elems[i].get_Some_0() = pre.combiner_rid(i)
                assert(post.combiner_rid(i) == post.clients.index(i).get_Waiting_rid());
            };
        }

        transition!{
            combiner_go_to_responding() {
                require(pre.combiner.is_Collecting());
                require(pre.combiner.get_Collecting_elems().len() == pre.num_clients);
                update combiner = Combiner::Responding{
                    elems: pre.combiner.get_Collecting_elems(),
                    idx: 0,
                };
            }
        }

        transition!{
            combiner_send(response: Response, cur_slot: bool) {
                require(pre.combiner.is_Responding());
                let j = pre.combiner.get_Responding_idx();
                require(0 <= j && j < pre.num_clients);
                let response_opt = pre.combiner.get_Responding_elems().index(j as int);

                // The response we return has to have the right request ID
                require(response_opt == Option::Some(response.rid));

                // Set the slot back to false
                remove slots -= [j => cur_slot];
                add    slots += [j => false];

                // Update the combiner's local state
                update combiner = Combiner::Responding{
                    elems: pre.combiner.get_Responding_elems(),
                    idx: j + 1,
                };

                deposit responses += [j => response] by {
                    assert(pre.valid_idx(j));
                    assert(pre.combiner_has(j));
                    assert(!pre.response_stored(j));
                };
            }
        }

        #[inductive(combiner_send)]
        fn combiner_send_inductive(pre: Self, post: Self, response: Response, cur_slot: bool) {
            let j = pre.combiner.get_Responding_idx();
            let elems = pre.combiner.get_Responding_elems();

            // not_waiting_inv: for i == j, post.slots[j] = false, so !post.slots[j] is true
            // regardless of whether client is Idle. For i != j, clients and slots unchanged.
            assert forall |i: nat| #[trigger] post.valid_idx(i) && post.clients.index(i).is_Idle()
                implies !post.slots.index(i) by {
                if i == j {
                    // post.slots[j] = false
                    assert(!post.slots.index(j));
                } else {
                    // clients[i] and slots[i] unchanged from pre
                    assert(pre.valid_idx(i));
                    assert(pre.clients.index(i).is_Idle());
                    assert(!pre.slots.index(i));
                }
            };

            // waiting_inv: for i == j, response_stored_post(j) is true (just deposited).
            // For i != j with combiner_has_pre(i): i >= j && i != j => i >= j+1 =>
            // combiner_has_post(i) holds (same elems, idx only increased).
            assert forall |i: nat| #[trigger] post.client_waiting(i)
                implies post.request_stored(i) || post.response_stored(i) || post.combiner_has(i) by {
                if i == j {
                    // We just deposited response[j]
                    assert(post.response_stored(j));
                } else {
                    // clients[i] unchanged
                    assert(pre.client_waiting(i));
                    if pre.request_stored(i) {
                        assert(post.request_stored(i));
                    } else if pre.response_stored(i) {
                        // responses[j] was added; for i != j, response[i] unchanged
                        assert(post.response_stored(i));
                    } else {
                        assert(pre.combiner_has(i));
                        // pre.combiner_has(i): i >= j && elems[i].is_Some()
                        // i != j => i >= j+1 => post.combiner_has(i): i >= j+1 (same elems)
                        assert(post.combiner_has(i));
                    }
                }
            };

            // request_stored_inv: requests unchanged. For i == j:
            // from combiner_has_inv_pre, combiner_has_pre(j) => !request_stored_pre(j).
            // So request[j] not in domain. For i != j: clients[i] unchanged.
            // Slots: slots[j] = false now, but j is not in requests.dom().
            assert forall |i: nat| #[trigger] post.request_stored(i)
                implies post.client_waiting(i)
                    && post.requests.index(i).rid == post.clients.index(i).get_Waiting_rid()
                    && post.slots.index(i) by {
                // requests unchanged
                assert(pre.request_stored(i));
                if i == j {
                    // combiner_has_pre(j) => !request_stored_pre(j) => contradiction
                    assert(pre.combiner_has(j));
                    assert(!pre.request_stored(j));
                } else {
                    // clients[i] unchanged for i != j
                    assert(pre.client_waiting(i));
                    assert(pre.requests.index(i).rid == pre.clients.index(i).get_Waiting_rid());
                    assert(pre.slots.index(i));
                    assert(post.slots.index(i));
                }
            };

            // response_stored_inv: for i == j, we just deposited response[j].
            // - client_waiting_post(j) = client_waiting_pre(j) (clients unchanged)
            //   and combiner_has_pre(j) => client_waiting_pre(j)
            // - response.rid = elems[j].get_Some_0() = combiner_rid_pre(j)
            //   and combiner_has_inv_pre: combiner_rid_pre(j) = clients[j].get_Waiting_rid()
            // - !post.slots[j]: slots[j] = false in post
            // For i != j: responses[i] unchanged, clients[i] unchanged, slots[i] unchanged.
            assert forall |i: nat| #[trigger] post.response_stored(i)
                implies post.client_waiting(i)
                    && post.responses.index(i).rid == post.clients.index(i).get_Waiting_rid()
                    && !post.slots.index(i) by {
                if i == j {
                    // From combiner_has_pre(j):
                    assert(pre.combiner_has(j));
                    assert(pre.client_waiting(j));
                    assert(post.client_waiting(j));
                    // combiner_rid_pre(j) = clients[j].get_Waiting_rid()
                    assert(pre.combiner_rid(j) == pre.clients.index(j).get_Waiting_rid());
                    // response.rid = elems[j].get_Some_0() = combiner_rid_pre(j)
                    assert(post.responses.index(j).rid == post.clients.index(j).get_Waiting_rid());
                    // post.slots[j] = false
                    assert(!post.slots.index(j));
                } else {
                    // responses[i] unchanged for i != j
                    assert(pre.response_stored(i));
                    assert(pre.client_waiting(i));
                    assert(post.client_waiting(i));
                    assert(post.responses.index(i).rid == post.clients.index(i).get_Waiting_rid());
                    assert(!post.slots.index(i));
                }
            };

            // combiner_has_inv: for i with combiner_has_post(i): i >= j+1.
            // Since i >= j+1 > j, pre.combiner_has(i) holds (same elems, i >= j).
            // Pre invariant: client_waiting(i), slots_pre[i] = true, rid matches,
            // !request_stored_pre(i). For i != j: clients[i], slots[i], requests unchanged.
            // For i == j: combiner_has_post(j) = (j >= j+1 && ...) = false. Not triggered.
            assert forall |i: nat| #[trigger] post.combiner_has(i)
                implies post.client_waiting(i)
                    && post.slots.index(i)
                    && post.combiner_rid(i) == post.clients.index(i).get_Waiting_rid()
                    && !post.request_stored(i) by {
                // post.combiner = Responding{elems, idx: j+1}
                // post.combiner_has(i): i >= j+1 && elems[i].is_Some()
                // => i > j, so pre.combiner_has(i): i >= j && elems[i].is_Some() = true
                assert(pre.combiner_has(i));
                assert(pre.client_waiting(i));
                assert(pre.slots.index(i));
                assert(pre.combiner_rid(i) == pre.clients.index(i).get_Waiting_rid());
                assert(!pre.request_stored(i));
                // i > j, so i != j: clients[i] and slots[i] unchanged
                assert(post.client_waiting(i));
                assert(post.slots.index(i));
                assert(post.combiner_rid(i) == post.clients.index(i).get_Waiting_rid());
                assert(!post.request_stored(i));
            };
        }

        transition!{
            combiner_send_skip() {
                require(pre.combiner.is_Responding());
                let j = pre.combiner.get_Responding_idx();
                require(0 <= j && j < pre.num_clients);
                let response_opt = pre.combiner.get_Responding_elems().index(j as int);

                // The response we return has to have the right request ID
                require(equal(response_opt, Option::None));

                // Update the combiner's local state
                update combiner = Combiner::Responding{
                    elems: pre.combiner.get_Responding_elems(),
                    idx: j + 1,
                };
            }
        }

        #[inductive(combiner_send_skip)]
        fn combiner_send_skip_inductive(pre: Self, post: Self) {
            let j = pre.combiner.get_Responding_idx();
            let elems = pre.combiner.get_Responding_elems();

            // clients_size: idx = j+1 <= num_clients (j < num_clients). Automatic.

            // not_waiting_inv: clients and slots unchanged. Automatic.

            // waiting_inv: combiner changed (idx: j -> j+1). For i == j:
            // combiner_has_pre(j): j >= j && elems[j].is_Some(). But elems[j] = None.
            // So combiner_has_pre(j) = false. From pre.waiting_inv: request_stored or response_stored.
            // Both unchanged. For i != j (with combiner_has_pre(i) true):
            // i >= j && i != j => i >= j+1 => combiner_has_post(i).
            assert forall |i: nat| #[trigger] post.client_waiting(i)
                implies post.request_stored(i) || post.response_stored(i) || post.combiner_has(i) by {
                // clients unchanged
                assert(pre.client_waiting(i));
                if pre.request_stored(i) {
                    assert(post.request_stored(i));
                } else if pre.response_stored(i) {
                    assert(post.response_stored(i));
                } else {
                    assert(pre.combiner_has(i));
                    // pre.combiner_has(i): i >= j && elems[i].is_Some()
                    // elems[j] = None, so i != j (otherwise elems[j].is_Some() would be false)
                    // i >= j && i != j => i >= j+1 => post.combiner_has(i)
                    assert(post.combiner_has(i));
                }
            };

            // request_stored_inv: requests, clients, slots unchanged. Automatic.
            // response_stored_inv: responses, clients, slots unchanged. Automatic.

            // combiner_has_inv: post.combiner_has(i): i >= j+1 && elems[i].is_Some().
            // => i >= j+1 > j, so pre.combiner_has(i) holds (same elems, i >= j).
            // Pre invariant applies. Clients, slots, requests unchanged.
            assert forall |i: nat| #[trigger] post.combiner_has(i)
                implies post.client_waiting(i)
                    && post.slots.index(i)
                    && post.combiner_rid(i) == post.clients.index(i).get_Waiting_rid()
                    && !post.request_stored(i) by {
                // i >= j+1 => pre.combiner_has(i)
                assert(pre.combiner_has(i));
                assert(pre.client_waiting(i));
                assert(pre.slots.index(i));
                assert(pre.combiner_rid(i) == pre.clients.index(i).get_Waiting_rid());
                assert(!pre.request_stored(i));
            };
        }

        #[inductive(combiner_go_to_responding)]
        fn combiner_go_to_responding_inductive(pre: Self, post: Self) {
            let elems = pre.combiner.get_Collecting_elems();

            // clients_size: Responding{elems, idx:0}, elems.len() = num_clients, 0 <= num_clients.

            // not_waiting_inv: clients and slots unchanged. Automatic.

            // waiting_inv: combiner changed: Collecting{elems} -> Responding{elems, idx:0}.
            // combiner_has_post(i): valid_idx(i) && i >= 0 && elems[i].is_Some().
            // Since i >= 0 always, combiner_has_post(i) = valid_idx(i) && elems[i].is_Some().
            // combiner_has_pre(i): valid_idx(i) && i < elems.len() && elems[i].is_Some().
            // elems.len() = num_clients, so i < elems.len() iff valid_idx(i).
            // So combiner_has_post(i) = combiner_has_pre(i).
            assert forall |i: nat| #[trigger] post.client_waiting(i)
                implies post.request_stored(i) || post.response_stored(i) || post.combiner_has(i) by {
                assert(pre.client_waiting(i));
                if pre.request_stored(i) {
                    assert(post.request_stored(i));
                } else if pre.response_stored(i) {
                    assert(post.response_stored(i));
                } else {
                    assert(pre.combiner_has(i));
                    // combiner_has_pre(i): i < elems.len() = num_clients && elems[i].is_Some()
                    // combiner_has_post(i): i >= 0 && elems[i].is_Some() (and valid_idx(i))
                    assert(post.combiner_has(i));
                }
            };

            // combiner_has_inv: post.combiner_has(i) = pre.combiner_has(i) (as shown above).
            // Pre invariant applies. Clients, slots, requests unchanged.
            assert forall |i: nat| #[trigger] post.combiner_has(i)
                implies post.client_waiting(i)
                    && post.slots.index(i)
                    && post.combiner_rid(i) == post.clients.index(i).get_Waiting_rid()
                    && !post.request_stored(i) by {
                assert(pre.combiner_has(i));
                assert(pre.client_waiting(i));
                assert(pre.slots.index(i));
                assert(pre.combiner_rid(i) == pre.clients.index(i).get_Waiting_rid());
                assert(!pre.request_stored(i));
            };
        }

        transition!{
            combiner_go_to_collecting() {
                require(pre.combiner.is_Responding());
                require(pre.combiner.get_Responding_idx() == pre.num_clients);
                update combiner = Combiner::Collecting{ elems: Seq::empty() };
            }
        }

        #[inductive(combiner_go_to_collecting)]
        fn combiner_go_to_collecting_inductive(pre: Self, post: Self) {
            // clients_size: Collecting{[]}.len() = 0 <= num_clients. Automatic.

            // not_waiting_inv: clients and slots unchanged. Automatic.

            // waiting_inv: post.combiner = Collecting{[]}.
            // combiner_has_post(i): i < 0 && ... = false for all i (since 0 is the empty seq len).
            // So for client_waiting(i): need request_stored or response_stored.
            // From pre: request_stored || response_stored || combiner_has_pre(i).
            // combiner_has_pre(i): valid_idx(i) && i >= num_clients && elems[i].is_Some().
            // But valid_idx(i) means i < num_clients. So combiner_has_pre(i) = false.
            // Hence from pre: request_stored_pre(i) || response_stored_pre(i). Both unchanged.
            assert forall |i: nat| #[trigger] post.client_waiting(i)
                implies post.request_stored(i) || post.response_stored(i) || post.combiner_has(i) by {
                assert(pre.client_waiting(i));
                if pre.request_stored(i) {
                    assert(post.request_stored(i));
                } else if pre.response_stored(i) {
                    assert(post.response_stored(i));
                } else {
                    // combiner_has_pre(i) = false (i < num_clients but need i >= num_clients)
                    assert(pre.combiner_has(i));
                    // This leads to contradiction: valid_idx(i) && i >= num_clients is false
                    // So this branch is unreachable
                }
            };

            // combiner_has_inv: post.combiner_has(i) = false for all i (empty seq).
            // Not triggered. Automatic.
        }

    }
}

fn main() {}

