// rust_verify/tests/example.rs expect-warnings
#[allow(unused_imports)]
use verus_builtin::*;
use verus_builtin_macros::*;
use vstd::map::*;
use vstd::multiset::*;
use vstd::prelude::*;
use vstd::seq::*;
use vstd::{pervasive::*, *};

use verus_state_machines_macros::tokenized_state_machine;

// Based off of the FlatCombine system from Seagull-NR.
// A major difference is that one didn't make any use of storage, because storage was
// rather complicated to use, and it wasn't necessary.
// Now, I expect storage to be a lot easier to use, easier than the alternative.

verus! {

pub struct Request {
    pub rid: int,
    pub req: int,
}

pub struct Response {
    pub rid: int,
    pub resp: int,
}

#[is_variant]
pub enum Client {
    Idle,
    Waiting { rid: int },
}

#[is_variant]
pub enum Combiner {
    Collecting { elems: Seq<Option<int>> },
    Responding { elems: Seq<Option<int>>, idx: nat },
}

} // verus!
tokenized_state_machine! {
    FlatCombiner {
        fields {
            #[sharding(constant)]
            pub num_clients: nat,

            #[sharding(imap)]
            pub clients: IMap<nat, Client>,

            #[sharding(imap)]
            pub slots: IMap<nat, bool>,

            #[sharding(variable)]
            pub combiner: Combiner,

            #[sharding(storage_imap)]
            pub requests: IMap<nat, Request>,

            #[sharding(storage_imap)]
            pub responses: IMap<nat, Response>,
        }

        pub open spec fn valid_idx(self, i: nat) -> bool {
            0 <= i && i < self.num_clients
        }

        #[invariant]
        pub fn clients_complete(self) -> bool {
            forall |i: nat| (0 <= i && i < self.num_clients) ==
                self.clients.dom().contains(i)
        }

        #[invariant]
        pub fn slots_complete(self) -> bool {
            forall |i: nat| (0 <= i && i < self.num_clients) ==
                self.slots.dom().contains(i)
        }

        #[invariant]
        pub fn clients_size(self) -> bool {
            match self.combiner {
                Combiner::Collecting{elems} => elems.len() <= self.num_clients,
                Combiner::Responding{elems, idx} => elems.len() == self.num_clients &&
                    0 <= idx && idx <= self.num_clients,
            }
        }

        /*
        #[verifier::spec]
        fn should_have_req_stored(self, i: nat) -> bool {
            0 <= i
            && i < self.slots
            && self.slots.index(i)
            && match self.combiner {
                Combiner::Collecting{elems} => elems.len() < i || elems.index(i).is_None()
                Combiner::Responding{elems, idx} => idx >= i || elems.index(i).is_None()
            }
        }
        */

        pub open spec fn client_waiting(self, i: nat) -> bool {
            self.valid_idx(i)
            && self.clients.index(i).is_Waiting()
        }

        pub open spec fn combiner_has(self, i: nat) -> bool {
            self.valid_idx(i)
            && match self.combiner {
                Combiner::Collecting{elems} => i < elems.len() && elems.index(i as int).is_Some(),
                Combiner::Responding{elems, idx} => i >= idx && elems.index(i as int).is_Some(),
            }
        }

        pub open spec fn combiner_rid(self, i: nat) -> int {
            match self.combiner {
                Combiner::Collecting{elems} => elems.index(i as int).get_Some_0(),
                Combiner::Responding{elems, idx} => elems.index(i as int).get_Some_0(),
            }
        }

        pub open spec fn request_stored(self, i: nat) -> bool {
            self.requests.dom().contains(i)
        }

        pub open spec fn response_stored(self, i: nat) -> bool {
            self.responses.dom().contains(i)
        }

        #[invariant]
        pub fn not_waiting_inv(self) -> bool {
            forall |i: nat| #[trigger] self.valid_idx(i) && self.clients.index(i).is_Idle() ==>
                !self.slots.index(i)
        }

        #[invariant]
        pub fn waiting_inv(self) -> bool {
            forall |i: nat| #[trigger] self.client_waiting(i) ==>
                self.request_stored(i) || self.response_stored(i) || self.combiner_has(i)
        }

        #[invariant]
        pub fn request_stored_inv(self) -> bool {
            forall |i: nat| #[trigger] self.request_stored(i) ==>
                self.client_waiting(i)
                && self.requests.index(i).rid == self.clients.index(i).get_Waiting_rid()
                && self.slots.index(i)
        }

        #[invariant]
        pub fn response_stored_inv(self) -> bool {
            forall |i: nat| #[trigger] self.response_stored(i) ==>
                self.client_waiting(i)
                && self.responses.index(i).rid == self.clients.index(i).get_Waiting_rid()
                && !self.slots.index(i)
        }


        #[invariant]
        pub fn combiner_has_inv(self) -> bool {
            forall |i: nat| #[trigger] self.combiner_has(i) ==>
                self.client_waiting(i)
                && self.slots.index(i)
                && self.combiner_rid(i) == self.clients.index(i).get_Waiting_rid()
                && !self.request_stored(i)
        }

        init!{
            initialize(num_clients: nat) {
                init num_clients = num_clients;
                init clients = IMap::new(
                    |i: nat| 0 <= i && i < num_clients,
                    |i: nat| Client::Idle);
                init slots = IMap::new(
                    |i: nat| 0 <= i && i < num_clients,
                    |i: nat| false);
                init combiner = Combiner::Collecting { elems: Seq::empty() };
                init requests = IMap::empty();
                init responses = IMap::empty();
            }
        }

        #[inductive(initialize)]
        fn init_inductive(post: Self, num_clients: nat) { }

        ///// Client transitions

        transition!{
            client_send(j: nat, request: Request, cur_slot: bool) {
                require(0 <= j && j < pre.num_clients);

                // Move client to 'waiting' state
                remove clients -= [j => Client::Idle];
                add    clients += [j => Client::Waiting{rid: request.rid}];

                // Set the slot
                remove slots -= [j => cur_slot];
                add    slots += [j => true];

                // deposit the request
                deposit requests += [j => request] by {
                    assert(!pre.request_stored(j));
                };
            }
        }

        #[inductive(client_send)]
        fn client_send_inductive(pre: Self,
            post: Self, j: nat, request: Request, cur_slot: bool)
        {
            // not_waiting_inv:
            // For i == j: post.clients[j] = Waiting (not Idle), so condition vacuously true.
            // For i != j: clients[i] and slots[i] unchanged from pre.
            assert forall |i: nat| #[trigger] post.valid_idx(i) && post.clients.index(i).is_Idle()
                implies !post.slots.index(i) by {
                if i == j {
                    // post.clients[j] = Waiting, so is_Idle() = false. Vacuously true.
                } else {
                    assert(pre.valid_idx(i));
                    assert(pre.clients.index(i).is_Idle());
                    assert(!pre.slots.index(i));
                }
            };

            // waiting_inv:
            // For i == j: request was just deposited, so request_stored_post(j) = true.
            // For i != j: all relevant fields unchanged (combiner unchanged).
            assert forall |i: nat| #[trigger] post.client_waiting(i)
                implies post.request_stored(i) || post.response_stored(i) || post.combiner_has(i) by {
                if i == j {
                    assert(post.request_stored(j));
                } else {
                    assert(pre.client_waiting(i));
                    if pre.request_stored(i) {
                        assert(post.request_stored(i));
                    } else if pre.response_stored(i) {
                        assert(post.response_stored(i));
                    } else {
                        assert(pre.combiner_has(i));
                        assert(post.combiner_has(i));
                    }
                }
            };

            // request_stored_inv:
            // For i == j: just deposited. Client is Waiting with rid = request.rid, slot = true.
            // For i != j: requests[i], clients[i], slots[i] all unchanged.
            assert forall |i: nat| #[trigger] post.request_stored(i)
                implies post.client_waiting(i)
                    && post.requests.index(i).rid == post.clients.index(i).get_Waiting_rid()
                    && post.slots.index(i) by {
                if i == j {
                    assert(post.client_waiting(j));
                    assert(post.requests.index(j).rid == request.rid);
                    assert(post.clients.index(j).get_Waiting_rid() == request.rid);
                    assert(post.slots.index(j));
                } else {
                    assert(pre.request_stored(i));
                    assert(pre.client_waiting(i));
                    assert(pre.requests.index(i).rid == pre.clients.index(i).get_Waiting_rid());
                    assert(pre.slots.index(i));
                }
            };

            // response_stored_inv:
            // For i == j: pre.clients[j] was Idle, so pre.response_stored(j) = false
            //   (response_stored_inv requires client_waiting). So post.response_stored(j) = false.
            //   This case is unreachable.
            // For i != j: responses[i], clients[i], slots[i] all unchanged.
            assert forall |i: nat| #[trigger] post.response_stored(i)
                implies post.client_waiting(i)
                    && post.responses.index(i).rid == post.clients.index(i).get_Waiting_rid()
                    && !post.slots.index(i) by {
                if i == j {
                    // pre.response_stored(j) must be false since pre.clients[j] was Idle.
                    // So post.response_stored(j) is also false (responses unchanged).
                    // This branch is unreachable.
                    assert(pre.response_stored(j));
                    assert(pre.client_waiting(j));
                    // Contradiction: pre.clients[j] was Idle.
                } else {
                    assert(pre.response_stored(i));
                    assert(pre.client_waiting(i));
                    assert(pre.responses.index(i).rid == pre.clients.index(i).get_Waiting_rid());
                    assert(!pre.slots.index(i));
                }
            };

            // combiner_has_inv:
            // Combiner is unchanged. For i with combiner_has_post(i) = combiner_has_pre(i):
            // pre.combiner_has_inv gives client_waiting_pre(i).
            // pre.clients[j] was Idle, so i != j.
            // For i != j: clients[i], slots[i], requests[i] unchanged.
            assert forall |i: nat| #[trigger] post.combiner_has(i)
                implies post.client_waiting(i)
                    && post.slots.index(i)
                    && post.combiner_rid(i) == post.clients.index(i).get_Waiting_rid()
                    && !post.request_stored(i) by {
                assert(pre.combiner_has(i));
                assert(pre.client_waiting(i));
                assert(pre.slots.index(i));
                assert(pre.combiner_rid(i) == pre.clients.index(i).get_Waiting_rid());
                assert(!pre.request_stored(i));
            };
        }

        transition!{
            client_recv(j: nat) {
                require(0 <= j && j < pre.num_clients);

                // Move client to 'idle' state
                remove clients -= [j => let Client::Waiting{rid}];
                add    clients += [j => Client::Idle];

                // Check that the slot has been set back to 'false'
                have slots >= [j => false];

                // withdraw the response
                withdraw responses -= [j => let response] by {
                    assert(pre.client_waiting(j));
                    //assert(!pre.request_stored(j));
                    //assert(!pre.combiner_has(j));
                    //assert(pre.response_stored(j));
                };

                // make sure we get back the response for the correct request id:
                assert(response.rid == rid) by {
                    assert(pre.client_waiting(j));
                };
            }
        }

        #[inductive(client_recv)]
        fn client_recv_inductive(pre: Self, post: Self, j: nat) {
            // not_waiting_inv:
            // For i == j: post.clients[j] = Idle, post.slots[j] = pre.slots[j] = false.
            //   So !post.slots[j] = true. ✓
            // For i != j: clients[i], slots[i] unchanged.
            assert forall |i: nat| #[trigger] post.valid_idx(i) && post.clients.index(i).is_Idle()
                implies !post.slots.index(i) by {
                if i == j {
                    // post.clients[j] = Idle, post.slots[j] = pre.slots[j] = false (from `have`)
                    assert(!post.slots.index(j));
                } else {
                    assert(pre.valid_idx(i));
                    assert(pre.clients.index(i).is_Idle());
                    assert(!pre.slots.index(i));
                }
            };

            // waiting_inv:
            // For i == j: post.clients[j] = Idle, so client_waiting is false. Vacuously true.
            // For i != j: clients[i] unchanged, responses[j] removed (but i != j so ok).
            assert forall |i: nat| #[trigger] post.client_waiting(i)
                implies post.request_stored(i) || post.response_stored(i) || post.combiner_has(i) by {
                if i == j {
                    // post.clients[j] = Idle, not Waiting. Vacuously true.
                } else {
                    assert(pre.client_waiting(i));
                    if pre.request_stored(i) {
                        assert(post.request_stored(i));
                    } else if pre.response_stored(i) {
                        // response[i] unchanged for i != j
                        assert(post.response_stored(i));
                    } else {
                        assert(pre.combiner_has(i));
                        assert(post.combiner_has(i));
                    }
                }
            };

            // request_stored_inv:
            // For i == j: pre.slots[j] = false, but request_stored_inv requires slot = true.
            //   So request_stored_pre(j) = false, and request_stored_post(j) = false. Unreachable.
            // For i != j: requests[i] unchanged, slots[i] unchanged.
            //   clients[j] changed, but i != j so clients[i] unchanged.
            assert forall |i: nat| #[trigger] post.request_stored(i)
                implies post.client_waiting(i)
                    && post.requests.index(i).rid == post.clients.index(i).get_Waiting_rid()
                    && post.slots.index(i) by {
                if i == j {
                    // request_stored_post(j) = request_stored_pre(j) (requests unchanged)
                    // but pre.slots[j] = false and pre.request_stored_inv => slots = true
                    // So pre.request_stored(j) = false => unreachable
                    assert(pre.request_stored(j));
                    assert(pre.slots.index(j));  // contradiction: pre.slots[j] = false
                } else {
                    assert(pre.request_stored(i));
                    assert(pre.client_waiting(i));
                    assert(pre.requests.index(i).rid == pre.clients.index(i).get_Waiting_rid());
                    assert(pre.slots.index(i));
                    // clients[i] unchanged for i != j
                    assert(post.client_waiting(i));
                    assert(post.requests.index(i).rid == post.clients.index(i).get_Waiting_rid());
                    assert(post.slots.index(i));
                }
            };

            // response_stored_inv:
            // For i == j: response[j] was withdrawn, so response_stored_post(j) = false. Unreachable.
            // For i != j: responses[i] unchanged.
            //   clients[j] changed to Idle, but i != j so clients[i] unchanged.
            assert forall |i: nat| #[trigger] post.response_stored(i)
                implies post.client_waiting(i)
                    && post.responses.index(i).rid == post.clients.index(i).get_Waiting_rid()
                    && !post.slots.index(i) by {
                if i == j {
                    // response[j] was withdrawn. Unreachable.
                } else {
                    assert(pre.response_stored(i));
                    assert(pre.client_waiting(i));
                    assert(pre.responses.index(i).rid == pre.clients.index(i).get_Waiting_rid());
                    assert(!pre.slots.index(i));
                    // clients[i] unchanged for i != j
                    assert(post.client_waiting(i));
                    assert(post.responses.index(i).rid == post.clients.index(i).get_Waiting_rid());
                    assert(!post.slots.index(i));
                }
            };

            // combiner_has_inv:
            // Combiner unchanged.
            // For i with combiner_has_post(i) = combiner_has_pre(i):
            // pre.combiner_has_inv => slots_pre[i] = true.
            // But if i == j: slots[j] = false. Contradiction. So i != j.
            // For i != j: clients[i] unchanged (clients[j] changed but i != j).
            assert forall |i: nat| #[trigger] post.combiner_has(i)
                implies post.client_waiting(i)
                    && post.slots.index(i)
                    && post.combiner_rid(i) == post.clients.index(i).get_Waiting_rid()
                    && !post.request_stored(i) by {
                assert(pre.combiner_has(i));
                assert(pre.slots.index(i));
                assert(pre.client_waiting(i));
                assert(pre.combiner_rid(i) == pre.clients.index(i).get_Waiting_rid());
                assert(!pre.request_stored(i));
                // Since pre.slots[i] = true and pre.slots[j] = false, we have i != j.
                // For i != j: clients[i] unchanged.
                assert(post.client_waiting(i));
                assert(post.combiner_rid(i) == post.clients.index(i).get_Waiting_rid());
            };
        }

        ///// Combiner transitions

        transition!{
            combiner_recv() {
                require(pre.combiner.is_Collecting());
                let j = pre.combiner.get_Collecting_elems().len();
                require(0 <= j && j < pre.num_clients);

                // Observe that the slot has been set to 'true'
                have slots >= [j => true];

                // Withdraw a request
                withdraw requests -= [j => let request] by {
                    assert(pre.valid_idx(j));
                    assert(pre.client_waiting(j));
                    assert(pre.request_stored(j));
                };

                // Update combiner's local state to remember we withdrew a request with this ID
                update combiner = Combiner::Collecting{
                    elems: pre.combiner.get_Collecting_elems().push(Option::Some(request.rid)),
                };
            }
        }

        #[inductive(combiner_recv)]
        fn combiner_recv_inductive(pre: Self, post: Self) {
            let j = pre.combiner.get_Collecting_elems().len() as nat;
            let old_elems = pre.combiner.get_Collecting_elems();
            let req_rid = pre.requests.index(j).rid;
            let new_elems = old_elems.push(Option::Some(req_rid));

            // Establish key facts about the new elems
            // j == old_elems.len() as nat, so j as int == old_elems.len() as int
            assert(j as int == old_elems.len() as int);
            // By lemma_seq_push_index_same: new_elems[j as int] = Some(req_rid)
            assert(new_elems.index(j as int) == Option::Some(req_rid)) by {
                broadcast use vstd::seq::group_seq_lemmas;
            };
            // post.combiner = Collecting{new_elems}
            // so post.combiner_rid(j) = new_elems[j].get_Some_0() = req_rid
            assert(post.combiner_rid(j) == req_rid);
            // From request_stored_inv: req_rid = clients[j].get_Waiting_rid()
            assert(pre.request_stored(j));
            assert(req_rid == pre.clients.index(j).get_Waiting_rid());

            // not_waiting_inv:
            // clients and slots unchanged. For any i with valid_idx and Idle client:
            assert forall |i: nat| #[trigger] post.valid_idx(i) && post.clients.index(i).is_Idle()
                implies !post.slots.index(i) by {
                assert(pre.valid_idx(i));
                assert(pre.clients.index(i).is_Idle());
                assert(!pre.slots.index(i));
            };

            // waiting_inv:
            // For i == j: combiner_has_post(j) is true (new_elems[j].is_Some()).
            // For i < j (combiner_has_pre(i)): post.combiner_has(i) also holds.
            assert forall |i: nat| #[trigger] post.client_waiting(i)
                implies post.request_stored(i) || post.response_stored(i) || post.combiner_has(i) by {
                if i == j {
                    // post.combiner = Collecting{new_elems}, j < new_elems.len() = j+1,
                    // and new_elems[j].is_Some() = true
                    assert(post.combiner_has(j));
                } else {
                    assert(pre.client_waiting(i));
                    if pre.request_stored(i) {
                        // request[i] unchanged for i != j
                        assert(post.request_stored(i));
                    } else if pre.response_stored(i) {
                        assert(post.response_stored(i));
                    } else {
                        assert(pre.combiner_has(i));
                        // pre.combiner_has(i): i < old_elems.len() = j && old_elems[i].is_Some()
                        // post.combiner_has(i): i < new_elems.len() = j+1 && new_elems[i].is_Some()
                        // Since i < j < j+1 and new_elems[i] = old_elems[i] (i < old_elems.len()):
                        assert(new_elems.index(i as int) == old_elems.index(i as int)) by {
                            broadcast use vstd::seq::group_seq_lemmas;
                        };
                        assert(post.combiner_has(i));
                    }
                }
            };

            // request_stored_inv:
            // request[j] was withdrawn. For i with request_stored_post(i): i != j.
            // For i != j: requests[i] unchanged, clients[i] unchanged, slots[i] unchanged.
            assert forall |i: nat| #[trigger] post.request_stored(i)
                implies post.client_waiting(i)
                    && post.requests.index(i).rid == post.clients.index(i).get_Waiting_rid()
                    && post.slots.index(i) by {
                if i == j {
                    // request[j] was withdrawn => post.request_stored(j) = false. Unreachable.
                } else {
                    assert(pre.request_stored(i));
                    assert(pre.client_waiting(i));
                    assert(pre.requests.index(i).rid == pre.clients.index(i).get_Waiting_rid());
                    assert(pre.slots.index(i));
                }
            };

            // response_stored_inv:
            // responses unchanged, clients unchanged, slots unchanged.
            assert forall |i: nat| #[trigger] post.response_stored(i)
                implies post.client_waiting(i)
                    && post.responses.index(i).rid == post.clients.index(i).get_Waiting_rid()
                    && !post.slots.index(i) by {
                assert(pre.response_stored(i));
                assert(pre.client_waiting(i));
                assert(pre.responses.index(i).rid == pre.clients.index(i).get_Waiting_rid());
                assert(!pre.slots.index(i));
            };

            // combiner_has_inv:
            // For i == j: combiner_has_post(j) = true.
            //   client_waiting_post(j) = client_waiting_pre(j) (clients unchanged) = true.
            //   post.slots.index(j) = true (slots unchanged, pre.slots[j] = true from `have`).
            //   post.combiner_rid(j) = req_rid = clients[j].get_Waiting_rid().
            //   !post.request_stored(j): request[j] was withdrawn.
            // For i < j (combiner_has_post(i)):
            //   pre.combiner_has(i): i < j && old_elems[i].is_Some() (same since new_elems[i] = old_elems[i]).
            //   Pre invariant applies. Clients, slots, requests unchanged.
            //   post.combiner_rid(i) = new_elems[i].get_Some_0() = old_elems[i].get_Some_0() = pre.combiner_rid(i).
            assert forall |i: nat| #[trigger] post.combiner_has(i)
                implies post.client_waiting(i)
                    && post.slots.index(i)
                    && post.combiner_rid(i) == post.clients.index(i).get_Waiting_rid()
                    && !post.request_stored(i) by {
                if i == j {
                    assert(post.client_waiting(j));
                    assert(post.slots.index(j));
                    assert(post.combiner_rid(j) == req_rid);
                    assert(post.combiner_rid(j) == post.clients.index(j).get_Waiting_rid());
                    assert(!post.request_stored(j));
                } else {
                    // post.combiner_has(i): i < j+1 && new_elems[i].is_Some(), and i != j, so i < j
                    // => pre.combiner_has(i) (since new_elems[i] = old_elems[i] for i < j)
                    assert(new_elems.index(i as int) == old_elems.index(i as int)) by {
                        broadcast use vstd::seq::group_seq_lemmas;
                    };
                    assert(pre.combiner_has(i));
                    assert(pre.client_waiting(i));
                    assert(pre.slots.index(i));
                    assert(pre.combiner_rid(i) == pre.clients.index(i).get_Waiting_rid());
                    assert(!pre.request_stored(i));
                    // For i != j: clients[i] unchanged, requests[i] unchanged.
                    // post.combiner_rid(i) = new_elems[i].get_Some_0() = old_elems[i].get_Some_0() = pre.combiner_rid(i)
                    assert(post.combiner_rid(i) == pre.combiner_rid(i));
                    assert(post.combiner_rid(i) == post.clients.index(i).get_Waiting_rid());
                    assert(!post.request_stored(i));
                }
            };
        }

        transition!{
            combiner_skip() {
                require(pre.combiner.is_Collecting());
                let j = pre.combiner.get_Collecting_elems().len();
                require(0 <= j && j < pre.num_clients);

                // In practice, this happens when slot j is set to false, so we could add this:
                //    have slots >= [j => false];
                // but it's not necessary

                // Update combiner's local state to remember that we didn't withdraw
                // anything here.
                update combiner = Combiner::Collecting{
                    elems: pre.combiner.get_Collecting_elems().push(Option::None),
                };
            }
        }

        #[inductive(combiner_skip)]
        fn combiner_skip_inductive(pre: Self, post: Self) {
            let j = pre.combiner.get_Collecting_elems().len() as nat;
            let old_elems = pre.combiner.get_Collecting_elems();
            let new_elems = old_elems.push(Option::None);

            // Establish that new_elems[j] = None (so combiner_has_post(j) = false)
            assert(j as int == old_elems.len() as int);
            assert(new_elems.index(j as int) == Option::None) by {
                broadcast use vstd::seq::group_seq_lemmas;
            };

            // not_waiting_inv: clients and slots unchanged.
            assert forall |i: nat| #[trigger] post.valid_idx(i) && post.clients.index(i).is_Idle()
                implies !post.slots.index(i) by {
                assert(pre.valid_idx(i));
                assert(pre.clients.index(i).is_Idle());
                assert(!pre.slots.index(i));
            };

            // waiting_inv:
            // For i == j: combiner_has_post(j) = false (new_elems[j] = None).
            //   From pre.waiting_inv: request_stored_pre(j) || response_stored_pre(j) || combiner_has_pre(j).
            //   combiner_has_pre(j): j < old_elems.len() = j => false. So request or response stored.
            //   Both unchanged in post.
            // For i != j with combiner_has_pre(i) (i < j): post.combiner_has(i) holds.
            assert forall |i: nat| #[trigger] post.client_waiting(i)
                implies post.request_stored(i) || post.response_stored(i) || post.combiner_has(i) by {
                assert(pre.client_waiting(i));
                if pre.request_stored(i) {
                    assert(post.request_stored(i));
                } else if pre.response_stored(i) {
                    assert(post.response_stored(i));
                } else {
                    assert(pre.combiner_has(i));
                    // pre.combiner_has(i): i < old_elems.len() = j && old_elems[i].is_Some()
                    // i != j since new_elems[j] = None but combiner_has_pre(i) means old_elems[i].is_Some()
                    // For i < j: new_elems[i] = old_elems[i]
                    assert(new_elems.index(i as int) == old_elems.index(i as int)) by {
                        broadcast use vstd::seq::group_seq_lemmas;
                    };
                    assert(post.combiner_has(i));
                }
            };

            // request_stored_inv: requests, clients, slots unchanged.
            assert forall |i: nat| #[trigger] post.request_stored(i)
                implies post.client_waiting(i)
                    && post.requests.index(i).rid == post.clients.index(i).get_Waiting_rid()
                    && post.slots.index(i) by {
                assert(pre.request_stored(i));
                assert(pre.client_waiting(i));
                assert(pre.requests.index(i).rid == pre.clients.index(i).get_Waiting_rid());
                assert(pre.slots.index(i));
            };

            // response_stored_inv: responses, clients, slots unchanged.
            assert forall |i: nat| #[trigger] post.response_stored(i)
                implies post.client_waiting(i)
                    && post.responses.index(i).rid == post.clients.index(i).get_Waiting_rid()
                    && !post.slots.index(i) by {
                assert(pre.response_stored(i));
                assert(pre.client_waiting(i));
                assert(pre.responses.index(i).rid == pre.clients.index(i).get_Waiting_rid());
                assert(!pre.slots.index(i));
            };

            // combiner_has_inv:
            // post.combiner_has(i): i < new_elems.len() = j+1 && new_elems[i].is_Some().
            // new_elems[j] = None, so i != j, hence i < j.
            // So pre.combiner_has(i) holds (new_elems[i] = old_elems[i] for i < j).
            // Pre invariant applies. Clients, slots, requests unchanged.
            // post.combiner_rid(i) = new_elems[i].get_Some_0() = old_elems[i].get_Some_0() = pre.combiner_rid(i).
            assert forall |i: nat| #[trigger] post.combiner_has(i)
                implies post.client_waiting(i)
                    && post.slots.index(i)
                    && post.combiner_rid(i) == post.clients.index(i).get_Waiting_rid()
                    && !post.request_stored(i) by {
                // i < j since new_elems[j] = None but post.combiner_has(i) needs new_elems[i].is_Some()
                assert(new_elems.index(i as int) == old_elems.index(i as int)) by {
                    broadcast use vstd::seq::group_seq_lemmas;
                };
                assert(pre.combiner_has(i));
                assert(pre.client_waiting(i));
                assert(pre.slots.index(i));
                assert(pre.combiner_rid(i) == pre.clients.index(i).get_Waiting_rid());
                assert(!pre.request_stored(i));
                assert(post.combiner_rid(i) == pre.combiner_rid(i));
                assert(post.combiner_rid(i) == post.clients.index(i).get_Waiting_rid());
            };
        }

        transition!{
            combiner_go_to_responding() {
                require(pre.combiner.is_Collecting());
                require(pre.combiner.get_Collecting_elems().len() == pre.num_clients);
                update combiner = Combiner::Responding{
                    elems: pre.combiner.get_Collecting_elems(),
                    idx: 0,
                };
            }
        }

        transition!{
            combiner_send(response: Response, cur_slot: bool) {
                require(pre.combiner.is_Responding());
                let j = pre.combiner.get_Responding_idx();
                require(0 <= j && j < pre.num_clients);
                let response_opt = pre.combiner.get_Responding_elems().index(j as int);

                // The response we return has to have the right request ID
                require(response_opt == Option::Some(response.rid));

                // Set the slot back to false
                remove slots -= [j => cur_slot];
                add    slots += [j => false];

                // Update the combiner's local state
                update combiner = Combiner::Responding{
                    elems: pre.combiner.get_Responding_elems(),
                    idx: j + 1,
                };

                deposit responses += [j => response] by {
                    assert(pre.valid_idx(j));
                    assert(pre.combiner_has(j));
                    assert(!pre.response_stored(j));
                };
            }
        }

        #[inductive(combiner_send)]
        fn combiner_send_inductive(pre: Self, post: Self, response: Response, cur_slot: bool) {
            let j = pre.combiner.get_Responding_idx();
            let elems = pre.combiner.get_Responding_elems();

            // not_waiting_inv: for i == j, post.slots[j] = false => !post.slots[j].
            // For i != j, clients[i] and slots[i] unchanged from pre.
            assert forall |i: nat| #[trigger] post.valid_idx(i) && post.clients.index(i).is_Idle()
                implies !post.slots.index(i) by {
                if i == j {
                    assert(!post.slots.index(j));
                } else {
                    assert(pre.valid_idx(i));
                    assert(pre.clients.index(i).is_Idle());
                    assert(!pre.slots.index(i));
                }
            };

            // waiting_inv: for i == j, response_stored_post(j) = true (just deposited).
            // For i != j with combiner_has_pre(i): i >= j && i != j => i >= j+1 =>
            // combiner_has_post(i) holds (same elems, increased idx).
            assert forall |i: nat| #[trigger] post.client_waiting(i)
                implies post.request_stored(i) || post.response_stored(i) || post.combiner_has(i) by {
                if i == j {
                    assert(post.response_stored(j));
                } else {
                    assert(pre.client_waiting(i));
                    if pre.request_stored(i) {
                        assert(post.request_stored(i));
                    } else if pre.response_stored(i) {
                        assert(post.response_stored(i));
                    } else {
                        assert(pre.combiner_has(i));
                        assert(post.combiner_has(i));
                    }
                }
            };

            // request_stored_inv: requests unchanged.
            // For i == j: combiner_has_pre(j) => !request_stored_pre(j) (from combiner_has_inv).
            //   So request_stored_post(j) = false. Unreachable.
            // For i != j: clients[i] unchanged. Slots[j] changed but i != j so slots[i] unchanged.
            assert forall |i: nat| #[trigger] post.request_stored(i)
                implies post.client_waiting(i)
                    && post.requests.index(i).rid == post.clients.index(i).get_Waiting_rid()
                    && post.slots.index(i) by {
                assert(pre.request_stored(i));
                if i == j {
                    assert(pre.combiner_has(j));
                    assert(!pre.request_stored(j));
                } else {
                    assert(pre.client_waiting(i));
                    assert(pre.requests.index(i).rid == pre.clients.index(i).get_Waiting_rid());
                    assert(pre.slots.index(i));
                    assert(post.slots.index(i));
                }
            };

            // response_stored_inv: for i == j, just deposited.
            //   - client_waiting_post(j) = client_waiting_pre(j) (clients unchanged).
            //     combiner_has_pre(j) => client_waiting_pre(j).
            //   - response.rid = elems[j].get_Some_0() = combiner_rid_pre(j)
            //     and combiner_has_inv => combiner_rid_pre(j) = clients[j].get_Waiting_rid().
            //   - !post.slots[j] = !false = true.
            // For i != j: responses[i], clients[i], slots[i] unchanged.
            assert forall |i: nat| #[trigger] post.response_stored(i)
                implies post.client_waiting(i)
                    && post.responses.index(i).rid == post.clients.index(i).get_Waiting_rid()
                    && !post.slots.index(i) by {
                if i == j {
                    assert(pre.combiner_has(j));
                    assert(pre.client_waiting(j));
                    assert(post.client_waiting(j));
                    assert(pre.combiner_rid(j) == pre.clients.index(j).get_Waiting_rid());
                    // response.rid = elems[j].get_Some_0() = combiner_rid_pre(j)
                    assert(post.responses.index(j).rid == post.clients.index(j).get_Waiting_rid());
                    assert(!post.slots.index(j));
                } else {
                    assert(pre.response_stored(i));
                    assert(pre.client_waiting(i));
                    assert(post.client_waiting(i));
                    assert(pre.responses.index(i).rid == pre.clients.index(i).get_Waiting_rid());
                    assert(post.responses.index(i).rid == post.clients.index(i).get_Waiting_rid());
                    assert(!post.slots.index(i));
                }
            };

            // combiner_has_inv: for i with combiner_has_post(i): i >= j+1.
            // Since i >= j+1 > j, pre.combiner_has(i) holds (same elems, i >= j).
            // For i != j: clients[i] and slots[i] unchanged.
            assert forall |i: nat| #[trigger] post.combiner_has(i)
                implies post.client_waiting(i)
                    && post.slots.index(i)
                    && post.combiner_rid(i) == post.clients.index(i).get_Waiting_rid()
                    && !post.request_stored(i) by {
                assert(pre.combiner_has(i));
                assert(pre.client_waiting(i));
                assert(pre.slots.index(i));
                assert(pre.combiner_rid(i) == pre.clients.index(i).get_Waiting_rid());
                assert(!pre.request_stored(i));
                // i > j, so i != j: clients[i] and slots[i] unchanged
                assert(post.client_waiting(i));
                assert(post.slots.index(i));
                assert(post.combiner_rid(i) == post.clients.index(i).get_Waiting_rid());
                assert(!post.request_stored(i));
            };
        }

        transition!{
            combiner_send_skip() {
                require(pre.combiner.is_Responding());
                let j = pre.combiner.get_Responding_idx();
                require(0 <= j && j < pre.num_clients);
                let response_opt = pre.combiner.get_Responding_elems().index(j as int);

                // The response we return has to have the right request ID
                require(equal(response_opt, Option::None));

                // Update the combiner's local state
                update combiner = Combiner::Responding{
                    elems: pre.combiner.get_Responding_elems(),
                    idx: j + 1,
                };
            }
        }

        #[inductive(combiner_send_skip)]
        fn combiner_send_skip_inductive(pre: Self, post: Self) {
            let j = pre.combiner.get_Responding_idx();
            let elems = pre.combiner.get_Responding_elems();

            // not_waiting_inv: clients and slots unchanged.
            assert forall |i: nat| #[trigger] post.valid_idx(i) && post.clients.index(i).is_Idle()
                implies !post.slots.index(i) by {
                assert(pre.valid_idx(i));
                assert(pre.clients.index(i).is_Idle());
                assert(!pre.slots.index(i));
            };

            // waiting_inv: combiner changed: idx j -> j+1.
            // For i == j: combiner_has_pre(j) = (j >= j && elems[j].is_Some()) = elems[j].is_Some() = false.
            //   From pre.waiting_inv: request_stored || response_stored. Both unchanged.
            // For i != j with combiner_has_pre(i) (i >= j && i != j => i >= j+1):
            //   post.combiner_has(i): i >= j+1 => true. Same elems.
            assert forall |i: nat| #[trigger] post.client_waiting(i)
                implies post.request_stored(i) || post.response_stored(i) || post.combiner_has(i) by {
                assert(pre.client_waiting(i));
                if pre.request_stored(i) {
                    assert(post.request_stored(i));
                } else if pre.response_stored(i) {
                    assert(post.response_stored(i));
                } else {
                    assert(pre.combiner_has(i));
                    // pre.combiner_has(i): i >= j && elems[i].is_Some()
                    // elems[j] = None, so i != j (otherwise elems[j].is_Some() = false)
                    // i != j and i >= j => i >= j+1 => post.combiner_has(i)
                    assert(post.combiner_has(i));
                }
            };

            // request_stored_inv: requests, clients, slots unchanged.
            assert forall |i: nat| #[trigger] post.request_stored(i)
                implies post.client_waiting(i)
                    && post.requests.index(i).rid == post.clients.index(i).get_Waiting_rid()
                    && post.slots.index(i) by {
                assert(pre.request_stored(i));
                assert(pre.client_waiting(i));
                assert(pre.requests.index(i).rid == pre.clients.index(i).get_Waiting_rid());
                assert(pre.slots.index(i));
            };

            // response_stored_inv: responses, clients, slots unchanged.
            assert forall |i: nat| #[trigger] post.response_stored(i)
                implies post.client_waiting(i)
                    && post.responses.index(i).rid == post.clients.index(i).get_Waiting_rid()
                    && !post.slots.index(i) by {
                assert(pre.response_stored(i));
                assert(pre.client_waiting(i));
                assert(pre.responses.index(i).rid == pre.clients.index(i).get_Waiting_rid());
                assert(!pre.slots.index(i));
            };

            // combiner_has_inv: post.combiner_has(i): i >= j+1 && elems[i].is_Some().
            // => i >= j+1 > j => pre.combiner_has(i) holds (i >= j, same elems).
            // Pre invariant: client_waiting(i), slots[i] = true, rid, !request_stored(i).
            // Clients, slots, requests unchanged.
            assert forall |i: nat| #[trigger] post.combiner_has(i)
                implies post.client_waiting(i)
                    && post.slots.index(i)
                    && post.combiner_rid(i) == post.clients.index(i).get_Waiting_rid()
                    && !post.request_stored(i) by {
                assert(pre.combiner_has(i));
                assert(pre.client_waiting(i));
                assert(pre.slots.index(i));
                assert(pre.combiner_rid(i) == pre.clients.index(i).get_Waiting_rid());
                assert(!pre.request_stored(i));
            };
        }

        #[inductive(combiner_go_to_responding)]
        fn combiner_go_to_responding_inductive(pre: Self, post: Self) {
            let elems = pre.combiner.get_Collecting_elems();
            // post.combiner = Responding{elems, idx: 0}
            // combiner_has_post(i): valid_idx(i) && i >= 0 && elems[i].is_Some()
            // combiner_has_pre(i): valid_idx(i) && i < elems.len() && elems[i].is_Some()
            // Since elems.len() = num_clients and valid_idx(i) means i < num_clients:
            // combiner_has_post(i) = valid_idx(i) && elems[i].is_Some() = combiner_has_pre(i)

            // not_waiting_inv: clients and slots unchanged.
            assert forall |i: nat| #[trigger] post.valid_idx(i) && post.clients.index(i).is_Idle()
                implies !post.slots.index(i) by {
                assert(pre.valid_idx(i));
                assert(pre.clients.index(i).is_Idle());
                assert(!pre.slots.index(i));
            };

            // waiting_inv: combiner changed but combiner_has is preserved.
            assert forall |i: nat| #[trigger] post.client_waiting(i)
                implies post.request_stored(i) || post.response_stored(i) || post.combiner_has(i) by {
                assert(pre.client_waiting(i));
                if pre.request_stored(i) {
                    assert(post.request_stored(i));
                } else if pre.response_stored(i) {
                    assert(post.response_stored(i));
                } else {
                    assert(pre.combiner_has(i));
                    // combiner_has_pre(i): i < elems.len() = num_clients && elems[i].is_Some()
                    // combiner_has_post(i): valid_idx(i) && i >= 0 && elems[i].is_Some()
                    // Since i < num_clients => i >= 0 (nat), this holds.
                    assert(post.combiner_has(i));
                }
            };

            // request_stored_inv: requests, clients, slots unchanged.
            assert forall |i: nat| #[trigger] post.request_stored(i)
                implies post.client_waiting(i)
                    && post.requests.index(i).rid == post.clients.index(i).get_Waiting_rid()
                    && post.slots.index(i) by {
                assert(pre.request_stored(i));
                assert(pre.client_waiting(i));
                assert(pre.requests.index(i).rid == pre.clients.index(i).get_Waiting_rid());
                assert(pre.slots.index(i));
            };

            // response_stored_inv: responses, clients, slots unchanged.
            assert forall |i: nat| #[trigger] post.response_stored(i)
                implies post.client_waiting(i)
                    && post.responses.index(i).rid == post.clients.index(i).get_Waiting_rid()
                    && !post.slots.index(i) by {
                assert(pre.response_stored(i));
                assert(pre.client_waiting(i));
                assert(pre.responses.index(i).rid == pre.clients.index(i).get_Waiting_rid());
                assert(!pre.slots.index(i));
            };

            // combiner_has_inv: post.combiner_has(i) = pre.combiner_has(i) (as shown above).
            // Pre invariant applies. Clients, slots, requests unchanged.
            // post.combiner_rid(i) = elems[i].get_Some_0() = pre.combiner_rid(i).
            assert forall |i: nat| #[trigger] post.combiner_has(i)
                implies post.client_waiting(i)
                    && post.slots.index(i)
                    && post.combiner_rid(i) == post.clients.index(i).get_Waiting_rid()
                    && !post.request_stored(i) by {
                assert(pre.combiner_has(i));
                assert(pre.client_waiting(i));
                assert(pre.slots.index(i));
                assert(pre.combiner_rid(i) == pre.clients.index(i).get_Waiting_rid());
                assert(!pre.request_stored(i));
                assert(post.combiner_rid(i) == pre.combiner_rid(i));
                assert(post.combiner_rid(i) == post.clients.index(i).get_Waiting_rid());
            };
        }

        transition!{
            combiner_go_to_collecting() {
                require(pre.combiner.is_Responding());
                require(pre.combiner.get_Responding_idx() == pre.num_clients);
                update combiner = Combiner::Collecting{ elems: Seq::empty() };
            }
        }

        #[inductive(combiner_go_to_collecting)]
        fn combiner_go_to_collecting_inductive(pre: Self, post: Self) {
            // post.combiner = Collecting{[]}
            // combiner_has_post(i) = i < 0 && ... = false for all i. Not triggered.

            // not_waiting_inv: clients and slots unchanged.
            assert forall |i: nat| #[trigger] post.valid_idx(i) && post.clients.index(i).is_Idle()
                implies !post.slots.index(i) by {
                assert(pre.valid_idx(i));
                assert(pre.clients.index(i).is_Idle());
                assert(!pre.slots.index(i));
            };

            // waiting_inv: post.combiner_has(i) = false for all i (empty seq has len 0).
            // So for client_waiting(i): need request_stored or response_stored.
            // From pre: request_stored || response_stored || combiner_has_pre(i).
            // Pre.combiner = Responding{elems, idx: num_clients}.
            // combiner_has_pre(i): valid_idx(i) && i >= num_clients && ... = false (valid_idx requires i < num_clients).
            // So from pre: request_stored_pre(i) || response_stored_pre(i). Both unchanged.
            assert forall |i: nat| #[trigger] post.client_waiting(i)
                implies post.request_stored(i) || post.response_stored(i) || post.combiner_has(i) by {
                assert(pre.client_waiting(i));
                if pre.request_stored(i) {
                    assert(post.request_stored(i));
                } else if pre.response_stored(i) {
                    assert(post.response_stored(i));
                } else {
                    // combiner_has_pre(i) = false since valid_idx(i) requires i < num_clients
                    // but combiner_has_pre requires i >= num_clients. Contradiction.
                    assert(pre.combiner_has(i));
                    // valid_idx(i) && i >= num_clients is false since valid_idx means i < num_clients
                    assert(pre.valid_idx(i));
                    assert(i < pre.num_clients);
                    // pre.combiner.is_Responding() with idx = num_clients
                    // combiner_has_pre(i) requires i >= num_clients. Contradiction.
                    assert(false);
                }
            };

            // request_stored_inv: requests, clients, slots unchanged.
            assert forall |i: nat| #[trigger] post.request_stored(i)
                implies post.client_waiting(i)
                    && post.requests.index(i).rid == post.clients.index(i).get_Waiting_rid()
                    && post.slots.index(i) by {
                assert(pre.request_stored(i));
                assert(pre.client_waiting(i));
                assert(pre.requests.index(i).rid == pre.clients.index(i).get_Waiting_rid());
                assert(pre.slots.index(i));
            };

            // response_stored_inv: responses, clients, slots unchanged.
            assert forall |i: nat| #[trigger] post.response_stored(i)
                implies post.client_waiting(i)
                    && post.responses.index(i).rid == post.clients.index(i).get_Waiting_rid()
                    && !post.slots.index(i) by {
                assert(pre.response_stored(i));
                assert(pre.client_waiting(i));
                assert(pre.responses.index(i).rid == pre.clients.index(i).get_Waiting_rid());
                assert(!pre.slots.index(i));
            };
        }

    }
}

